.eon8-live-page .seo-wrap {
    max-width:1200px;
    margin:auto;
}
.eon8-live-page .seo-title {
    text-align:center;
    margin-bottom:50px;
}
.eon8-live-page .seo-title h2 {
    font-size:34px;
    font-weight:800;
    color:#1a2a6c;
}
.eon8-live-page .seo-title p {
    color:#555;
    max-width:700px;
    margin:auto;
}
.eon8-live-page .seo-cards {
    display:grid;
    grid-template-columns:repeat(auto-fit, minmax(300px,1fr));
    gap:25px;
}
.eon8-live-page .seo-card {
    position:relative;
    background:#fff;
    padding:25px;
    border-radius:16px;
    overflow:hidden;
    transition:0.4s;
    opacity:0;
    transform:translateY(40px);
}
.eon8-live-page .seo-card::before {
    content:"";
    position:absolute;
    inset:0;
    padding:2px;
    border-radius:16px;
    background:linear-gradient(120deg,#ff6a00,#2da7df,#ff6a00);
    -webkit-mask: 
        linear-gradient(#fff 0 0) content-box, 
        linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
    animation: borderMove 4s linear infinite;
}
@keyframes borderMove {
    0% { background-position:0% }
    100% { background-position:200% }
}
.eon8-live-page .seo-card:hover {
    transform:translateY(-12px) scale(1.02);
    box-shadow:0 15px 40px rgba(0,0,0,0.12);
}
.eon8-live-page .seo-card h3 {
    font-size:18px;
    margin-bottom:10px;
    font-weight:700;
}
.eon8-live-page .seo-card p {
    font-size:14px;
    color:#555;
    line-height:1.7;
}
.eon8-live-page .show {
    opacity:1 !important;
    transform:translateY(0) !important;
}
.eon8-live-page .seo-footer {
    text-align:center;
    margin-top:50px;
    color:#666;
}
@media(max-width:768px) {.eon8-live-page .seo-title h2 {
        font-size:26px;
    }}
.eon8-live-page .eon-box {
        position: relative;
        display: inline-block;
        padding: 60px 30px;
        border-radius: 120px;
        background: linear-gradient(135deg, #ff6a00, #ff3d00);
        color: #fff;
        overflow: hidden;
        animation: float 4s ease-in-out infinite;
    }
.eon8-live-page .eon-box::before {
        content: "";
        position: absolute;
        width: 200%;
        height: 200%;
        top: -50%;
        left: -50%;
        background: conic-gradient(
            rgba(255,255,255,0.3),
            transparent,
            rgba(255,255,255,0.3)
        );
        animation: rotate 6s linear infinite;
    }
.eon8-live-page .eon-content {
        position: relative;
        z-index: 2;
    }
.eon8-live-page .eon-box::after {
        content: "";
        position: absolute;
        inset: 0;
        border-radius: 120px;
        box-shadow: 0 0 40px rgba(255,106,0,0.4);
        opacity: 0.7;
        animation: pulse 2.5s infinite;
    }
@keyframes rotate {
        0% { transform: rotate(0deg); }
        100% { transform: rotate(360deg); }
    }
@keyframes float {
        0%,100% { transform: translateY(0); }
        50% { transform: translateY(-12px); }
    }
@keyframes pulse {
        0% { opacity: 0.6; }
        50% { opacity: 1; }
        100% { opacity: 0.6; }
    }
.eon8-live-page .dot {
        position:absolute;
        width:8px;
        height:8px;
        background:#fff;
        border-radius:50%;
        opacity:0.7;
        animation: moveDot 6s infinite linear;
    }
.eon8-live-page .dot1 { top:10%; left:20%; }
.eon8-live-page .dot2 { bottom:15%; right:25%; animation-delay:2s; }
.eon8-live-page .dot3 { top:50%; left:80%; animation-delay:4s; }
@keyframes moveDot {
        0% { transform: translateY(0); }
        50% { transform: translateY(-15px); }
        100% { transform: translateY(0); }
    }
